<template><main class="hh-page urgent-followup"><router-link to="/contrareferencias" class="hh-back-link d-inline-flex align-items-center mb-3"><i class="ph ph-arrow-left me-1"></i>Volver a contrarreferencias</router-link><section class="followup-hero"><div><span>SEGUIMIENTO CLÍNICO</span><h1>Controles urgentes</h1><p>Pacientes con control vencido o programado durante los próximos siete días.</p></div><button class="btn btn-light text-primary" :disabled="loading" @click="load"><i class="ph ph-arrows-clockwise me-1"></i>Actualizar</button></section><div v-if="error" class="alert alert-danger mt-3">{{error}}</div><div v-if="loading" class="text-center py-5"><span class="spinner-border text-primary"></span></div><section v-else class="followup-grid mt-4"><div v-if="!items.length" class="empty"><i class="ph ph-calendar-check"></i><h3>Sin controles urgentes</h3><p>No hay seguimientos vencidos ni próximos.</p></div><article v-for="item in sorted" :key="item.id" :class="urgencyClass(item)"><header><span><i :class="days(item)<0?'ph ph-warning':'ph ph-calendar-dots'"></i></span><div><small>{{item.referencia?.numero_referencia||`Contrarreferencia #${item.id}`}}</small><h3>{{patient(item)}}</h3><p>{{item.referencia?.paciente?.identificacion}}</p></div><em>{{dayLabel(item)}}</em></header><div class="followup-info"><div><small>Próximo control</small><strong>{{formatDate(item.fecha_proximo_control)}}</strong></div><div><small>Especialidad</small><strong>{{item.especialidad_seguimiento||'No informada'}}</strong></div><div><small>Frecuencia</small><strong>{{item.frecuencia_seguimiento||'No informada'}}</strong></div><div><small>Médico</small><strong>{{item.medico_contrarefiere?.name||item.medico?.name||'No informado'}}</strong></div><div class="origin"><small>Establecimiento de origen</small><strong>{{item.referencia?.establecimiento_origen?.nombre||'No informado'}}</strong></div></div><footer><router-link :to="`/referencias/${item.referencia_id||item.referencia?.id}/contrareferencia`" class="btn btn-sm btn-primary">Abrir seguimiento <i class="ph ph-arrow-right ms-1"></i></router-link></footer></article></section></main></template>
<script setup>import{computed,onMounted,ref}from'vue';import{obtenerMensajeError}from'@/services/api';import{listarSeguimientoUrgente}from'@/services/referencias';const items=ref([]),loading=ref(false),error=ref(''),array=v=>Array.isArray(v)?v:Array.isArray(v?.data)?v.data:[],patient=x=>x.referencia?.paciente?.nombre||x.paciente?.nombre||'Paciente no informado',dateOnly=v=>new Date(`${String(v).slice(0,10)}T00:00:00`),days=x=>Math.ceil((dateOnly(x.fecha_proximo_control)-dateOnly(new Date().toISOString().slice(0,10)))/86400000),sorted=computed(()=>[...items.value].sort((a,b)=>days(a)-days(b))),urgencyClass=x=>days(x)<0?'overdue':days(x)<=2?'imminent':'upcoming',dayLabel=x=>days(x)<0?`${Math.abs(days(x))} días vencido`:days(x)===0?'Control hoy':days(x)===1?'Control mañana':`En ${days(x)} días`,formatDate=v=>v?new Intl.DateTimeFormat('es-CO',{dateStyle:'long'}).format(dateOnly(v)):'Sin fecha';async function load(){loading.value=true;error.value='';try{items.value=array(await listarSeguimientoUrgente())}catch(e){error.value=obtenerMensajeError(e)}finally{loading.value=false}}onMounted(load)</script>
<style scoped>.followup-hero{display:flex;align-items:center;justify-content:space-between;padding:1.4rem 1.5rem;border-radius:1rem;background:linear-gradient(120deg,#0b5587,#148fbc);color:#fff}.followup-hero span{font-size:.6rem;font-weight:800;letter-spacing:.08em}.followup-hero h1{margin:.2rem 0;font-size:1.55rem}.followup-hero p{margin:0;opacity:.82}.followup-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:.8rem}.followup-grid>article{overflow:hidden;border:1px solid #e0e7ed;border-top:4px solid #4a99c7;border-radius:.85rem;background:#fff;box-shadow:0 8px 24px rgba(24,64,96,.06)}.followup-grid>article.overdue{border-top-color:#cf414c}.followup-grid>article.imminent{border-top-color:#e2912f}.followup-grid article>header{display:flex;align-items:center;gap:.7rem;padding:.9rem 1rem;border-bottom:1px solid #e7ecf0}.followup-grid header>span{display:grid;place-items:center;width:41px;height:41px;border-radius:12px;background:#eaf4fb;color:var(--bs-primary);font-size:1.2rem}.overdue header>span{background:#fff0f1;color:#c83d49}.imminent header>span{background:#fff4df;color:#bd741c}.followup-grid header>div{min-width:0;flex:1}.followup-grid header small{color:#718096;font-size:.58rem}.followup-grid h3{margin:.1rem 0;font-size:.87rem}.followup-grid header p{margin:0;color:#8290a0;font-size:.63rem}.followup-grid header em{padding:.3rem .55rem;border-radius:20px;background:#e8f4fb;color:#2477a9;font-size:.63rem;font-style:normal;font-weight:800}.overdue header em{background:#fff0f1;color:#c43f4a}.imminent header em{background:#fff3df;color:#b5701b}.followup-info{display:grid;grid-template-columns:repeat(2,1fr);gap:.6rem;padding:.9rem 1rem}.followup-info small,.followup-info strong{display:block}.followup-info small{color:#8592a1;font-size:.58rem}.followup-info strong{font-size:.68rem}.followup-info .origin{grid-column:1/-1}.followup-grid article>footer{display:flex;justify-content:flex-end;padding:.75rem 1rem;border-top:1px solid #e7ecf0}.empty{grid-column:1/-1;text-align:center;padding:5rem;color:#718096}.empty i{font-size:3rem;color:#adc2d1}.empty h3{margin:.7rem 0 .2rem;font-size:1rem}@media(max-width:750px){.followup-grid{grid-template-columns:1fr}.followup-hero{align-items:flex-start;flex-direction:column;gap:1rem}}</style>
